package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationConfig;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.cfg.MapperConfig;
import com.fasterxml.jackson.databind.deser.BeanDescription;
import com.fasterxml.jackson.databind.deser.CreatorProperty;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.ValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ValueInstantiator.StdValueInstantiator;
import com.fasterxml.jackson.databind.deser.impl.ValueInstantiator.Vanilla;
import com.fasterxml.jackson.databind.deser.std.StdBeanProperty;
import com.fasterxml.jackson.databind.deser.std.StdValueInstantiator;
import com.fasterxml.jackson.databind.introspect.*;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Member;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class CreatorCollector_constructValueInstantiator_TriageGen0Test {

    private DeserializationConfig config;
    private BeanDescription beanDesc;
    private JavaType javaType;
    private MapperConfig<?> mapperConfig;

    @Before
    public void setup() {
        config = mock(DeserializationConfig.class);
        beanDesc = mock(BeanDescription.class);
        javaType = mock(JavaType.class);
        mapperConfig = mock(MapperConfig.class);

        when(beanDesc.getType()).thenReturn(javaType);
    }

    /**
     * Tests the "Vanilla" optimization path for Collections (List/ArrayList)
     * when no non-default creators exist.
     */
    @Test
    public void testConstructValueInstantiator_VanillaCollection() {
        when(javaType.getRawClass()).thenReturn(List.class);

        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        // hasDefaultCreator is false by default if no creators added, 
        // and _hasNonDefaultCreator logic depends on the presence of specific creators.
        // In actual implementation, we ensure no non-default creators are added.

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        // Vanilla for Collection type check (internal check via type constant if possible)
        // Since we can't easily check private field, we check behavior or class type
        assertTrue(instantiator.getClass().getName().contains("Vanilla"));
    }

    @Test
    public void testConstructValueInstantiator_VanillaArrayList() {
        when(javaType.getRawClass()).thenReturn(ArrayList.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);
        assertNotNull(instantiator);
    }

    @Test
    public void testConstructValueInstantiator_VanillaMap() {
        when(javaType.getRawClass()).thenReturn(Map.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);
        assertNotNull(instantiator);
    }

    @Test
    public void testConstructValueInstantiator_VanillaLinkedHashMap() {
        when(javaType.getRawClass()).thenReturn(LinkedHashMap.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);
        assertNotNull(instantiator);
    }

    @Test
    public void testConstructValueInstantiator_VanillaHashMap() {
        when(javaType.getRawClass()).thenReturn(HashMap.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);
        assertNotNull(instantiator);
    }

    /**
     * Tests the StdValueInstantiator path when non-default creators are present.
     * This forces the code to bypass the Vanilla optimization.
     */
    @Test
    public void testConstructValueInstantiator_StdInstantiatorWithCreators() {
        when(javaType.getRawClass()).thenReturn(Object.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        // Adding a creator makes _hasNonDefaultCreator true
        // We use an AnnotatedWithParams mock to simulate a creator
        AnnotatedWithParams creator = mock(AnnotatedWithParams.class);
        collector.addStringCreator(creator);

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        // Should be StdValueInstantiator, not Vanilla
        assertFalse(instantiator.getClass().getName().contains("Vanilla"));
        assertTrue(instantiator.getClass().getName().contains("StdValueInstantiator"));
    }

    /**
     * Tests the path where hasNonDefaultCreator is false but the type is NOT a well-known collection.
     */
    @Test
    public void testConstructValueInstantiator_NotWellKnownTypeNoCreators() {
        when(javaType.getRawClass()).thenReturn(String.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        // No creators added -> _hasNonDefaultCreator is false
        // Type is String -> not in the Vanilla list
        // The code will fall through to create StdValueInstantiator
        ValueInstantiator instantiator = collector.constructValueInstantiator(config);

        assertNotNull(instantiator);
        assertFalse(instantiator.getClass().getName().contains("Vanilla"));
    }

    /**
     * Tests with an incomplete parameter to ensure configureIncompleteParameter is called.
     */
    @Test
    public void testConstructValueInstantiator_WithIncompleteParameter() {
        when(javaType.getRawClass()).thenReturn(Object.class);
        CreatorCollector collector = new CreatorCollector(beanDesc, mapperConfig);

        AnnotatedParameter param = mock(AnnotatedParameter.class);
        collector.addIncompeteParameter(param);

        // Add a creator to ensure we hit the Std path
        collector.addStringCreator(mock(AnnotatedWithParams.class));

        ValueInstantiator instantiator = collector.constructValueInstantiator(config);
        assertNotNull(instantiator);
    }
}
